  if not exists (select 1 from reading_passages where title = $q$When the Pictures Learned to Talk$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$When the Pictures Learned to Talk$q$, $q$Silent films were never really silent. In most theaters a pianist, an organist or even a small orchestra played along with the picture. Printed cards called intertitles carried the important lines of dialogue, and skilled actors told the rest of the story with their faces and their bodies. Because there was no recorded speech, the same print could be shown anywhere in the world with new cards in the local language. Studios in Europe, Japan and the United States all exported their films with little difficulty.

Inventors had been trying to join sound to film for years, but the results were quiet, brief or badly synchronized. Warner Brothers took a risk with a system that played music from large discs turning beside the projector. In 1927 the studio released The Jazz Singer, which combined a recorded score with a few songs and a short passage of speech. Audiences lined up around the block, and other studios understood that they could not afford to wait. Within about three years almost every American feature film was being made with sound.

The change was harder than it looked. Early microphones picked up every noise, so the camera had to be shut inside a padded box and could barely move. Actors were forced to stand near hidden microphones, and some performers with unsuitable voices lost their careers. Theaters had to install expensive equipment, and small ones in poor districts closed instead. Charlie Chaplin resisted the trend for years, releasing City Lights in 1931 with music and effects but no spoken dialogue.$q$, $q$culture / film$q$, 3, 255, true, $q$reading_shabbat_2026-09-05_E1$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, how did audiences learn what the characters were saying?$q$, $q$["An actor stood beside the screen and spoke all of the lines aloud.", "Printed cards showed the important lines between the scenes.", "The orchestra played a different melody for each character in the film.", "Programs handed out at the door contained the full text of the dialogue."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה שחקן שהקריא את הדיאלוג ליד המסך.", "נכון. הפסקה מציינת שכרטיסיות מודפסות, הקרויות intertitles, נשאו את שורות הדיאלוג החשובות.", "לא נכון. הפסקה מזכירה ליווי מוזיקלי, אך לא מנגינה נפרדת לכל דמות.", "לא נכון. הפסקה אינה מזכירה תוכניות שחולקו לקהל."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch E1, passage=silent-to-sound, q1$q$, 1, true);
