    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the second paragraph, how did the Warner Brothers system produce the sound?$q$, $q$["From large discs that turned next to the projector.", "From a magnetic strip attached to the edge of the film itself.", "From loudspeakers behind the screen that the pianist controlled.", "From musicians hidden below the stage who followed a written score."]$q$::jsonb, 0, $q$["נכון. הפסקה מציינת שוורנר ברדרס השתמשה במערכת שניגנה מוזיקה מתקליטים גדולים שהסתובבו לצד המקרן.", "לא נכון. הפסקה אינה מזכירה פס מגנטי על סרט הצילום.", "לא נכון. הרמקולים והפסנתרן אינם מוזכרים כמקור הצליל במערכת הזו.", "לא נכון. נגנים חיים מתוארים בפסקה הראשונה כליווי לסרט האילם, ולא כמערכת של וורנר."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["a system that played music from large discs turning beside the projector"]$q$::jsonb, $q$shabbat batch E1, passage=silent-to-sound, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the third paragraph, all of the following are true EXCEPT —$q$, $q$["The camera had to be enclosed so that microphones would not record its noise.", "Some actors lost their careers because their voices did not suit the new films.", "Small theaters in poor districts shut down rather than buy the new equipment.", "Charlie Chaplin adopted spoken dialogue earlier than most other filmmakers."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש.", "לא נכון. זו קביעה נכונה על פי הפסקה השלישית, ולכן אינה החריג המבוקש.", "נכון. זו הקביעה השגויה: הפסקה כותבת שצ'פלין התנגד למגמה במשך שנים והוציא ב-1931 סרט בלי דיאלוג מדובר."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Charlie Chaplin resisted the trend for years"]$q$::jsonb, $q$shabbat batch E1, passage=silent-to-sound, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the export of films after 1927?$q$, $q$["It became more complicated, because recorded speech was tied to one language.", "It stopped completely until dubbing equipment was invented in the 1930s.", "It grew easier, since recorded sound made the stories clearer to foreign viewers.", "It was controlled by a single company that owned the patents on sound."]$q$::jsonb, 0, $q$["נכון. הפסקה הראשונה מסבירה שהיעדר דיבור מוקלט איפשר להחליף כרטיסיות בשפה המקומית, ומכאן שקול מוקלט הצמיד את הסרט לשפה אחת והקשה על הייצוא.", "לא נכון. הקטע אינו טוען שהייצוא נפסק לחלוטין.", "לא נכון. זו מסקנה הפוכה לרמז שבפסקה הראשונה על היתרון של סרטים ללא דיבור מוקלט.", "לא נכון. הקטע מזכיר את ורנר ברדרס כחלוצה, אך אינו מדבר על שליטה בפטנטים או על ייצוא."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch E1, passage=silent-to-sound, q5$q$, 5, true);
