  if not exists (select 1 from reading_passages where title = $q$A Penny to Stand at the Globe$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$A Penny to Stand at the Globe$q$, $q$The Globe Theatre opened in 1599 on the south bank of the River Thames, across the water from the city of London. It was built by the acting company to which William Shakespeare belonged, using timber taken from an older playhouse that they had dismantled. The site lay outside the control of the city authorities, who disapproved of plays and of the crowds they attracted. The building was a tall wooden ring with three levels of covered galleries around an open yard. Performances took place in the afternoon, since the stage depended entirely on daylight.

A place in the yard cost one penny, and those who paid it stood on their feet for the whole play. Wealthier visitors paid more for a bench in the galleries, and a cushion cost extra. Scholars estimate that the theatre could hold something close to three thousand people. The audience mixed apprentices, servants, merchants and gentlemen, which was unusual in a society organized around rank. Spectators ate, talked back to the actors and showed their opinions loudly, so a play had to hold their attention.

The stage itself was almost bare, with no painted scenery to explain where a scene was set. Instead the words did that work, which is why the plays describe forests, battlefields and moonlit nights so vividly. Women were not permitted to perform in public, so boys played the female parts. In 1613 a cannon fired during a performance set the thatched roof alight, and the theatre burned to the ground within an hour. A new Globe rose on the same site the following year, and a modern reconstruction opened nearby in 1997.$q$, $q$arts / theatre$q$, 3, 270, true, $q$reading_shabbat_2026-09-05_E1$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, why was the Globe built outside the city of London?$q$, $q$["The acting company could not afford any land inside the city walls.", "The site lay beyond the reach of officials who disliked plays and crowds.", "The riverbank gave the stage better daylight for afternoon performances.", "The older playhouse they had dismantled also stood on the south bank."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה מחירי קרקע או קשיים כספיים של הלהקה.", "נכון. הפסקה מציינת שהמגרש היה מחוץ לשליטת שלטונות העיר, שהתנגדו להצגות ולקהל שהן משכו.", "לא נכון. אור היום מוזכר כסיבה לשעת ההצגה, ולא כסיבה למיקום מחוץ לעיר.", "לא נכון. הפסקה אינה מציינת היכן עמד בית ההצגות הישן."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch E1, passage=globe-theatre, q1$q$, 1, true);
